(()=>{const grid=document.querySelector('#note-grid');if(!grid)return;let theme='all';const key='minds-gallery-custom-v1';let custom=[];document.querySelectorAll('.note-tools,.own-note,.note-actions').forEach(e=>e.hidden=false);const status=document.querySelector('#note-status');
function update(){let n=0;grid.querySelectorAll('.idea-note').forEach(c=>{const picked=c.querySelector('input').checked;c.classList.toggle('picked',picked);n+=picked?1:0;c.hidden=theme!=='all'&&c.dataset.group!==theme;});document.querySelector('#print-selected').disabled=!n;status.textContent=n+' selected';}
function wire(c){c.querySelector('input').addEventListener('change',update);c.querySelector('.copy-note').addEventListener('click',async()=>{const text=c.querySelector('h2').textContent+'\n'+c.querySelector('.note-copy').textContent;try{await navigator.clipboard.writeText(text);status.textContent='Copied: '+c.querySelector('h2').textContent}catch{const selection=getSelection(),range=document.createRange();range.selectNodeContents(c);selection.removeAllRanges();selection.addRange(range);status.textContent='Text selected. Use your browser’s Copy command.'}});}
function add(d){const c=document.createElement('article');c.className='idea-note';c.dataset.group='custom';c.innerHTML='<p class="note-kind">Your note · this browser only</p><h2></h2><p class="note-copy"></p><div class="note-actions"><label><input type="checkbox"> Print this note</label><button type="button" class="copy-note">Copy note</button></div>';c.querySelector('h2').textContent=d.title;c.querySelector('.note-copy').textContent=d.text;c.querySelector('input').setAttribute('aria-label','Select '+d.title);grid.append(c);wire(c);}
grid.querySelectorAll('.idea-note').forEach(wire);try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))custom=saved.filter(d=>typeof d.title==='string'&&typeof d.text==='string').map(d=>({title:d.title.slice(0,90),text:d.text.slice(0,240)}));custom.forEach(add)}catch{}
document.querySelectorAll('[data-theme]').forEach(b=>b.addEventListener('click',()=>{theme=b.dataset.theme;document.querySelectorAll('[data-theme]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));update()}));document.querySelector('#select-visible').addEventListener('click',()=>{grid.querySelectorAll('.idea-note:not([hidden]) input').forEach(x=>x.checked=true);update()});document.querySelector('#clear-selection').addEventListener('click',()=>{grid.querySelectorAll('input').forEach(x=>x.checked=false);update()});document.querySelector('#print-selected').addEventListener('click',()=>{document.body.classList.add('printing-selection');window.print()});addEventListener('afterprint',()=>document.body.classList.remove('printing-selection'));
document.querySelector('#add-note').addEventListener('submit',e=>{e.preventDefault();const title=document.querySelector('#own-title').value.trim(),text=document.querySelector('#own-text').value.trim();if(!title||!text)return;const d={title,text};custom.push(d);add(d);let saved=true;try{localStorage.setItem(key,JSON.stringify(custom))}catch{saved=false}document.querySelector('[data-theme=all]').click();e.target.reset();const last=grid.lastElementChild;last.scrollIntoView({block:'center',behavior:'instant'});status.textContent=saved?'Added and saved in this browser.':'Added for this tab only; browser storage is unavailable.';});update();})();
